package fu.fa26.sep490.g58.otcms_be.auth.service;
import fu.fa26.sep490.g58.otcms_be.auth.dto.*; import fu.fa26.sep490.g58.otcms_be.auth.entity.*; import fu.fa26.sep490.g58.otcms_be.auth.repository.*; import fu.fa26.sep490.g58.otcms_be.config.AuthProperties; import jakarta.persistence.EntityManager; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.transaction.annotation.Transactional; import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.util.HexFormat; import javax.crypto.Mac; import javax.crypto.spec.SecretKeySpec; import java.time.*; import java.util.*;
@Service public class CredentialLoginService {
 private final AccountRepository accounts; private final AuthenticationAuditRepository audits; private final PasswordEncoder encoder; private final AuthProperties props; private final EntityManager entityManager; private final Clock clock;
 @Autowired public CredentialLoginService(AccountRepository a,AuthenticationAuditRepository h,PasswordEncoder e,AuthProperties p,EntityManager em){this(a,h,e,p,em,Clock.systemUTC());} public CredentialLoginService(AccountRepository a,AuthenticationAuditRepository h,PasswordEncoder e,AuthProperties p,EntityManager em,Clock c){accounts=a;audits=h;encoder=e;props=p;entityManager=Objects.requireNonNull(em,"entityManager");clock=c;}
 @Transactional(noRollbackFor = CredentialLoginException.class) public CredentialLoginResponse login(String email,String password,AccountType portal,String ip){String n=normalize(email); Instant now=Instant.now(clock); enforceIpRate(ip); Account a=accounts.findByNormalizedEmail(n).orElse(null); boolean ok=a!=null&&a.getAccountType()==portal&&usable(a,now)&&a.getPasswordHash()!=null&&encoder.matches(password,a.getPasswordHash()); if(!ok){if(a!=null&&a.getAccountType()==portal) fail(a,now); audit(a,a==null?n:null,"LOGIN_"+portal,"AUTHENTICATION_FAILED"); throw new CredentialLoginException("AUTHENTICATION_FAILED");} a.setFailedCredentialCount(0);a.setLockedUntil(null);a.setUpdatedAt(now);accounts.save(a);audit(a,null,"LOGIN_"+portal,"SUCCESS");return new CredentialLoginResponse(a.getId(),a.getAccountType().name());}
 private boolean usable(Account a,Instant n){if(a.getStatus()==AccountStatus.ACTIVE)return true;if(a.getStatus()==AccountStatus.TEMPORARILY_LOCKED&&a.getLockedUntil()!=null&&!n.isBefore(a.getLockedUntil())){a.setStatus(AccountStatus.ACTIVE);a.setFailedCredentialCount(0);a.setLockedUntil(null);return true;}return false;}
 private void fail(Account a,Instant n){int x=a.getFailedCredentialCount()+1;a.setFailedCredentialCount(x);if(x>=props.credentialFailure().requests()){a.setStatus(AccountStatus.TEMPORARILY_LOCKED);a.setLockedUntil(n.plusSeconds(props.credentialFailure().windowSeconds()));}a.setUpdatedAt(n);accounts.save(a);}
 private void audit(Account a,String id,String method,String outcome){AuthenticationAudit h=new AuthenticationAudit();h.setOccurredAt(Instant.now(clock));h.setMethod(method);h.setOutcome(outcome);h.setAccount(a);h.setIdentifierHmac(a==null?hmac(id):null);h.setCorrelationId(UUID.randomUUID().toString());h.setClientIp(null);h.setDurationMs(0);audits.save(h);}
 private void enforceIpRate(String ip){String key=ip==null?"unknown":ip.trim(); String id=hmac(key); entityManager.createNativeQuery("select pg_advisory_xact_lock(hashtext(:key))").setParameter("key","login-ip:"+id).getSingleResult(); Instant since=Instant.now(clock).minusSeconds(props.login().windowSeconds()); if(audits.countByMethodAndOutcomeAndIdentifierHmacAndOccurredAtAfter("LOGIN_IP","ATTEMPT",id,since)>=props.login().requests()){throw new CredentialLoginException("RATE_LIMIT_EXCEEDED");} AuthenticationAudit h=new AuthenticationAudit();h.setOccurredAt(Instant.now(clock));h.setMethod("LOGIN_IP");h.setOutcome("ATTEMPT");h.setIdentifierHmac(id);h.setCorrelationId(UUID.randomUUID().toString());h.setClientIp(null);h.setDurationMs(0);audits.save(h);}
 private String hmac(String value){String secret=props.rateLimitHmacSecret();if(secret==null||secret.isBlank())throw new CredentialLoginException("RATE_LIMIT_UNAVAILABLE");try{Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));return HexFormat.of().formatHex(mac.doFinal(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception ex){throw new CredentialLoginException("RATE_LIMIT_UNAVAILABLE");}}
 private static String normalize(String s){return s==null?"":s.trim().toLowerCase(Locale.ROOT);}
}
